const body = $input.first().json.body || {};
const subject = String(body.subject || '').trim();
const text = String(body.text || '').trim();
const sender = String(body.from || '').trim();
const messageId = String(body.message_id || '').trim();

if (!subject && !text) {
  return [{ json: { valid: false, statusCode: 400, error: "Body must include a non-empty 'subject' or 'text' field." } }];
}
const limits = [
  [subject, 500, 'subject'],
  [text, 20000, 'text'],
  [sender, 320, 'from'],
  [messageId, 256, 'message_id']
];
const oversized = limits.find(([value, limit]) => value.length > limit);
if (oversized) {
  return [{ json: { valid: false, statusCode: 400, error: oversized[2] + ' exceeds the ' + oversized[1] + '-character limit.' } }];
}
return [{ json: { valid: true, message_id: messageId || null, from: sender || null, subject, text } }];

const email = $('Validate Email').first().json;
const raw = $input.first().json?.choices?.[0]?.message?.content;
const failure = (error) => [{ json: { valid: false, statusCode: 502, error } }];
if (typeof raw !== 'string' || !raw.trim()) {
  return failure('llama-server returned no task extraction.');
}
const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let payload;
try {
  payload = JSON.parse(cleaned);
} catch (error) {
  return failure('llama-server returned invalid JSON.');
}
if (!payload || !Array.isArray(payload.tasks) || payload.tasks.length > 20) {
  return failure('llama-server returned an invalid or oversized task list.');
}
const priorities = ['low', 'medium', 'high'];
const tasks = [];
for (const task of payload.tasks) {
  if (!task || typeof task !== 'object') {
    return failure('llama-server returned an invalid task entry.');
  }
  const title = typeof task.title === 'string' ? task.title.trim() : '';
  const details = typeof task.details === 'string' ? task.details.trim() : '';
  const priority = typeof task.priority === 'string' ? task.priority.toLowerCase() : '';
  const dueDate = task.due_date === null ? null : task.due_date;
  if (!title || title.length > 200 || details.length > 2000 || !priorities.includes(priority)) {
    return failure('llama-server returned a task outside the title, details, or priority contract.');
  }
  if (dueDate !== null && (typeof dueDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dueDate))) {
    return failure('llama-server returned an invalid due date.');
  }
  tasks.push({ title, details, priority, due_date: dueDate });
}
const summary = typeof payload.summary === 'string' ? payload.summary.trim() : '';
if (summary.length > 1000) {
  return failure('llama-server returned an oversized summary.');
}
return [{ json: { valid: true, statusCode: 200, message_id: email.message_id, from: email.from, subject: email.subject, summary, task_count: tasks.length, tasks } }];
